$$\begin{array}{l}
  {{average\ velocity} = \frac{change\ in\ position}{time\ elapsed}} \\
  {\phantom{average\ velocity} = \frac{s(5.1) - s(5)}{0.1}} \\
  {\phantom{average\ velocity} = \frac{4.9{(5.1)}^{2} - 4.9{(5)}^{2}}{0.1} = {49.49m \slash s}}
  \end{array}$$

$$\begin{array}{l}
  {{\lim\limits_{x\rightarrow\infty}{({\sqrt{x^{2} + 1} - x})}} = {\lim\limits_{x\rightarrow\infty}{({\sqrt{x^{2} + 1} - x})} \cdot \frac{\sqrt{x^{2} + 1} + x}{\sqrt{x^{2} + 1} + x}}} \\
  {\phantom{\lim\limits_{x\rightarrow\infty}{({\sqrt{x^{2} + 1} - x})}} = {\lim\limits_{x\rightarrow\infty}\frac{(x^{2} + 1) - x^{2}}{\sqrt{x^{2} + 1} + x} = \lim\limits_{x\rightarrow\infty}\frac{1}{\sqrt{x^{2} + 1} + x}}}
  \end{array}$$

$$\begin{array}{l}
  {m = {\lim\limits_{h\rightarrow 0}\frac{f{({3 + h})} - f{(3)}}{h}}} \\
  {\phantom{m} = {\lim\limits_{h\rightarrow 0}\frac{\frac{3}{3 + h} - 1}{h} = \lim\limits_{h\rightarrow 0}\frac{\frac{3 - {({3 + h})}}{3 + h}}{h}}} \\
  {\phantom{m} = {\lim\limits_{h\rightarrow 0}\frac{- h}{h{({3 + h})}} = \lim\limits_{h\rightarrow 0} - \frac{1}{3 + h} = - \frac{1}{3}}}
  \end{array}$$

$$\begin{array}{l}
  {{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({a + h})} - f{(a)}}{h} = \lim\limits_{h\rightarrow 0}\frac{4.9{({a + h})}^{2} - 4.9a^{2}}{h}}} \\
  {\phantom{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{4.9{({a^{2} + 2ah + h^{2} - a^{2}})}}{h} = \lim\limits_{h\rightarrow 0}\frac{4.9{({2ah + h^{2}})}}{h}}} \\
  {\phantom{\upsilon{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{4.9h{({2a + h})}}{h} = \lim\limits_{h\rightarrow 0}4.9{({2a + h})} = 9.8a}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({a + h})} - f{(a)}}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{{\lbrack{{({a + h})}^{2} - 8{({a + h})} + 9}\rbrack} - {\lbrack{a^{2} - 8a + 9}\rbrack}}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{a^{2} + 2ah + h^{2} - 8a - 8h + 9 - a^{2} + 8a - 9}{h}}} \\
  {\phantom{f^{\prime}{(a)}} = {\lim\limits_{h\rightarrow 0}\frac{2ah + h^{2} - 8h}{h} = \lim\limits_{h\rightarrow 0}{({2a + h - 8}) = {2a - 8}}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}{\frac{f(x + h) - f(x)}{h} = \lim\limits_{h\rightarrow 0}\frac{{\lbrack{{({x + h})}^{3} - {({x + h})}}\rbrack} - {\lbrack{x^{3} - x}\rbrack}}{h}}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{x^{3} + 3x^{2}h + 3xh^{2} + h^{3} - x - h - x^{3} + x}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{3x^{2}h + 3xh^{2} + h^{3} - h}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}{({3x^{2} + 3xh + h^{2} - 1})} = 3x^{2} - 1}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f(x + h) - f(x)}{h}} = {\lim\limits_{h\rightarrow 0}\frac{\sqrt{x + h} - \sqrt{x}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\left( {\frac{\sqrt{x + h} - \sqrt{x}}{h} \cdot \frac{\sqrt{x + h} + \sqrt{x}}{\sqrt{x + h} + \sqrt{x}}} \right)\qquad{({{Rationalize\ the\ numerator}.})}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{\frac{{({x + h})} - x}{h({\sqrt{x + h} + \sqrt{x}})} = \lim\limits_{h\rightarrow 0}\frac{h}{h({\sqrt{x + h} + \sqrt{x}})}}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{\frac{1}{\sqrt{x + h} + \sqrt{x}} = \frac{1}{\sqrt{x} + \sqrt{x}} = \frac{1}{2\sqrt{x}}}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{\left| x + h \middle| - \middle| x \right|}{h} = \lim\limits_{h\rightarrow 0}\frac{- \left( {x + h} \right) - \left( {- x} \right)}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{- h}{h} = \lim\limits_{h\rightarrow 0}\left( {- 1} \right) = - 1}}
  \end{array}$$
